insert into public.questions (id, topic_id, subtopic_id, question_text, question_type, difficulty, explanation, source, source_reference, status) values ('6c637b26-b83f-4c53-8902-732f0fb02ff6', (select t.id from public.topics t join public.exam_areas ea on ea.id = t.exam_area_id where t.name = 'Agricultural Machinery Design, Fabrication/Manufacturing and Testing' and ea.code = 'POWER_ENERGY_MACHINERY'), NULL, 'A 3-bladed 40-meter tall aerogenerator with 20 meters rotor radius designed for 6 m/s wind can''t rotate. Average windspeed at rotor center is 5.5 m/s. Which part needs to be increased?', 'single_choice', 'moderate', 'Windspeed is higher at higher elevation; increasing rotor radius will severely affect twist angle of entire blade & tip-speed ratio; aerogenerators have no crank arm.', 'Arthur It. Tambong, FPSAE', 'ABELE TOP 1/ATTRC/TAMBONG/Area 1/AREA1-2022.pdf', 'draft');
