insert into public.questions (id, topic_id, subtopic_id, question_text, question_type, difficulty, explanation, source, source_reference, status) values ('33228453-dfd8-415c-b814-0234f5050d3c', (select t.id from public.topics t join public.exam_areas ea on ea.id = t.exam_area_id where t.name = 'Agricultural Machinery Design, Fabrication/Manufacturing and Testing' and ea.code = 'POWER_ENERGY_MACHINERY'), NULL, 'A 2-tonne capacity Jatropha oil expeller was loaded full with dried Jatropha seeds in 3 minutes. It produced 750 kg of crude oil in 3 hours. What is its crude oil production rate?', 'single_choice', 'difficult', 'Poil = Weight of crude oil collected / Total time = 750 kg / 3 h = 250 kg/h [FLAGGED FOR REVIEW: Source prints choice B''s unit as ''kg/min'' but the source''s own solution computes 250 kg/h, matching the marked answer. Likely a unit typo in the original material — verify before publishing.]', 'Arthur It. Tambong, FPSAE', 'ABELE TOP 1/ATTRC/TAMBONG/Area 1/AREA1-2022.pdf', 'draft');
