insert into public.questions (id, topic_id, subtopic_id, question_text, question_type, difficulty, explanation, source, source_reference, status) values ('f0687ca1-9a47-490b-ad0c-0eb141118e65', (select t.id from public.topics t join public.exam_areas ea on ea.id = t.exam_area_id where t.name = 'Agricultural Machinery Design, Fabrication/Manufacturing and Testing' and ea.code = 'POWER_ENERGY_MACHINERY'), NULL, 'A castor bean oil expeller was loaded with 4.5 tonnes dried castor bean seeds. It produced 2,250 kg of crude oil in 4 hours. What is its castor bean cake production rate?', 'single_choice', 'difficult', 'Pcake = Weight of resulting cake produced / Total time = (4,500 kg seed - 2,250 kg oil) / 4 h = 562.5 kg/h', 'Arthur It. Tambong, FPSAE', 'ABELE TOP 1/ATTRC/TAMBONG/Area 1/AREA1-2022.pdf', 'draft');
