insert into public.questions (id, topic_id, subtopic_id, question_text, question_type, difficulty, explanation, source, source_reference, status) values ('95cafc06-411e-4b04-a56d-5c3fbc0e91e7', (select t.id from public.topics t join public.exam_areas ea on ea.id = t.exam_area_id where t.name = 'Agricultural Machinery Design, Fabrication/Manufacturing and Testing' and ea.code = 'POWER_ENERGY_MACHINERY'), NULL, 'A 10-tonne capacity coconut oil expeller was loaded full with grated copra. It produced 5,000 kg of crude oil in 10 hours. What is the copra cake production rate of the machine at 95% cake collection efficiency?', 'single_choice', 'difficult', 'Pcake = [(Wt. of copra input - Wt. of crude oil collected) / Total time] x Eff = [(10,000 kg - 5,000 kg) / 10 h] x 0.95 = 475 kg/h', 'Arthur It. Tambong, FPSAE', 'ABELE TOP 1/ATTRC/TAMBONG/Area 1/AREA1-2022.pdf', 'draft');
