insert into public.questions (id, topic_id, subtopic_id, question_text, question_type, difficulty, explanation, source, source_reference, status) values ('0355e146-41dd-40fe-8ab2-42c39a6c02ea', (select t.id from public.topics t join public.exam_areas ea on ea.id = t.exam_area_id where t.name = 'Agricultural Machinery Design, Fabrication/Manufacturing and Testing' and ea.code = 'POWER_ENERGY_MACHINERY'), NULL, 'What is the weight of agricultural waste that is needed annually to optimally operate a 26-ampere 6-kw vermi cast production shredder having a capacity of 0.3 tonne of waste per hour? It optimally operates 16 hours daily during the 4-month peak sunny months and 8 h/day at 26 days/month for the rest of the year.', 'single_choice', 'difficult', 'Wt = Input Rate x (Peak Operating Time + Lean Operating Time) = [0.3 tonne/h][(16 h/d x 30 d/mo x 4 mo/yr) + (8 h/d x 26 d/mo x 8 mos/yr)] = 1,075 tonnes/yr (per source) [FLAGGED FOR REVIEW: The source''s own worked solution computes 1,075 tonnes/yr, which is choice B — but the source marks ''Answer: C'' (1,750 tonnes). Internal inconsistency in the source material. Needs verification before publishing; do not treat either as confirmed correct without checking the original author''s material further.]', 'Arthur It. Tambong, FPSAE', 'ABELE TOP 1/ATTRC/TAMBONG/Area 1/AREA1-2022.pdf', 'draft');
