insert into public.questions (id, topic_id, subtopic_id, question_text, question_type, difficulty, explanation, source, source_reference, status) values ('c06256bf-8835-4bd2-8de7-2bc22d144405', (select t.id from public.topics t join public.exam_areas ea on ea.id = t.exam_area_id where t.name = 'Engineering Economy and Project Feasibility Analysis' and ea.code = 'PROJECT_MGMT_RDE'), NULL, 'At project start, the net cash flow of the cassava processing venture is -7 million pesos due to loan and revenue is not materialized yet. Discount rate is 10%. What is the value of the discounted cash flow in million pesos at project start?', 'single_choice', 'moderate', 'At project start or time=0, the discounted cash flow is also equal to the net cash flow.', 'Arthur It. Tambong, FPSAE', 'ABELE TOP 1/ATTRC/TAMBONG/Area 1/AREA1-2022.pdf', 'draft');
