insert into public.questions (id, topic_id, subtopic_id, question_text, question_type, difficulty, explanation, source, source_reference, status) values ('2ee5a097-0f60-4bea-922c-275bc0ffa1d9', (select t.id from public.topics t join public.exam_areas ea on ea.id = t.exam_area_id where t.name = 'Engineering Economy and Project Feasibility Analysis' and ea.code = 'PROJECT_MGMT_RDE'), NULL, 'Using financial feasibility analysis, the Net Present Values (NPVs) of farm-to-market road, irrigation and flood control projects are 22.5, 7.5 and -3.1 million pesos, while the Internal Rate of Returns (IRRs) are 15%, 7% and 2.1%, respectively. Annual discount plus inflation rate is 10%. Which project shall be implemented?', 'single_choice', 'difficult', 'Only the Farm-to-Market road project has IRR higher than discount plus inflation rate.', 'Arthur It. Tambong, FPSAE', 'ABELE TOP 1/ATTRC/TAMBONG/Area 1/AREA1-2022.pdf', 'draft');
insert into public.choices (id, question_id, choice_text, is_correct, sort_order) values ('4d851cf3-399b-459a-a9af-6ddbc1b83408', '2ee5a097-0f60-4bea-922c-275bc0ffa1d9', 'Farm-to-market road', true, 0);
