insert into public.choices (id, question_id, choice_text, is_correct, sort_order) values ('488c7cd1-a87b-41c4-b4d3-379bf0df3817', '2ee5a097-0f60-4bea-922c-275bc0ffa1d9', 'None', false, 3);
insert into public.questions (id, topic_id, subtopic_id, question_text, question_type, difficulty, explanation, source, source_reference, status) values ('d8a5dd2e-1c83-4953-8730-3a78bdb81b80', (select t.id from public.topics t join public.exam_areas ea on ea.id = t.exam_area_id where t.name = 'Engineering Economy and Project Feasibility Analysis' and ea.code = 'PROJECT_MGMT_RDE'), NULL, 'Using straight line depreciation method, what is the book value at the end of the third year of a tractor purchased at Php 2,500,000 if its life span is assumed at 10 years? Salvage value is 10%.', 'single_choice', 'difficult', 'Depreciation = (Php2,500,000 - Php250,000) / 10 years = Php 225,000/year. Book value = Purchase price - total depreciations = Php2,500,000 - (Php225,000/yr x 3yrs) = P1,825,000', 'Arthur It. Tambong, FPSAE', 'ABELE TOP 1/ATTRC/TAMBONG/Area 1/AREA1-2022.pdf', 'draft');
