insert into public.questions (id, topic_id, subtopic_id, question_text, question_type, difficulty, explanation, source, source_reference, status) values ('c7af9805-58f9-4245-9e6c-0ee178c485b1', (select t.id from public.topics t join public.exam_areas ea on ea.id = t.exam_area_id where t.name = 'Engineering Economy and Project Feasibility Analysis' and ea.code = 'PROJECT_MGMT_RDE'), NULL, 'A banana production and export project is being evaluated for financial feasibility. At 12% annual discount rate, it has the following feasibility indicators: net present value of 1.8 billion pesos and internal rate of return of 58%. If annual discount rate drops to 9%, will it be feasible?', 'single_choice', 'difficult', 'If it is feasible at 12% discount rate, the more it will be feasible at 9%.', 'Arthur It. Tambong, FPSAE', 'ABELE TOP 1/ATTRC/TAMBONG/Area 1/AREA1-2022.pdf', 'draft');
